#!/usr/bin/env bash
#
# CT-1 -- IRI generated by TARQL does not match the taxonomy/ontology concept IRI.
#
# The data carries both halves of the question, so the run tests whether the
# check *discriminates* rather than merely fires:
#
#   error case  ?site_IRI   built two ways across the two queries -> reported
#   control     ?asset_IRI  built identically in both             -> silent
#
# A check that reported both would be useless in exactly the way that matters,
# and one that reported neither would look identical to a passing project.
#
#   ./run.sh            run it
#   ./run.sh --show     run it and print every finding, not just the verdict
#
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
OUT="$HERE/out"

EXPECTED="TQL-001"       # the check this folder is about
ERROR_CASE="?site_IRI"   # must be reported
CONTROL="?asset_IRI"     # must not be

# Findings that are correct here and are not the point. Empty, and meant to
# stay that way: this folder's data seeds one defect and the run reports one
# finding. Anything that needs adding here is a claim that the suite reports
# something about data nobody wrote, and is worth reading twice before it is
# written down.
#
# It held CNF-002 until suite 0.20.0. The sketch wrote its namespace legend
# with the CURIE `:isRepresentedBy`, and `:` means the scratch namespace only
# when no query declares an empty prefix -- so the tool's own predicate
# landed in this model's namespace and was reported as a property nobody had
# declared. Fixed upstream rather than allowed for here.
ALLOWED=""

# Uses this repo's environment by default. Set SUITE to anything else that
# runs the CLI -- a global install, a container -- and the rest still works:
#   SUITE=ontology-quality-suite ./run.sh
SUITE=${SUITE:-"uv run --project $HERE/../../.. ontology-quality-suite"}

rm -rf "$OUT"
mkdir -p "$OUT"

# --reports minimal writes findings.txt (what, where, description) and
# full_results.csv (what this script greps) and nothing else. The default
# writes six artefacts -- report.html, cucumber.json, features/ and plots/ as
# well -- which is 20 files and a third of a megabyte for three findings, and
# a fixture folder is read as text or not at all. Needs suite 0.19.0.
#
# --fail-on never because the gate here is "was the seeded defect reported",
# not "were there findings". The suite's own exit code is 1 whenever it finds
# a Violation, which is what a fixture like this exists to produce.
#
# No --query-pattern: the default (*.sparql,*.rq,*.tarql,*.tq) matches the
# files in queries/ as they sit. Add --query-pattern "**/*.rq" only if you
# nest them in subfolders -- "**/" matches subfolders *only*, so passing it
# with a flat folder finds nothing at all.
# shellcheck disable=SC2086
$SUITE sketch \
  --queries "$HERE/queries" \
  --ontology "$HERE/ontologies/water.ttl" \
  --out-dir "$OUT" \
  --reports minimal \
  --fail-on never

RESULTS="$OUT/full_results.csv"
if [ ! -f "$RESULTS" ]; then
  echo "CT-1: FAIL -- the run wrote no $RESULTS" >&2
  exit 1
fi

if [ "${1:-}" = "--show" ]; then
  echo
  echo "--- every finding ---"
  cut -d, -f1,4,5 "$RESULTS"
fi

echo
STATUS=0

# 1. the seeded defect is reported, and reported about the right thing
if grep "^$EXPECTED," "$RESULTS" | grep -q ",$ERROR_CASE,"; then
  echo "CT-1: $EXPECTED reported for $ERROR_CASE -- sites.rq and readings.rq mint the"
  echo "      same :Site IRI from two different templates, so the two never join."
else
  echo "CT-1: FAIL -- $EXPECTED was not reported for $ERROR_CASE" >&2
  STATUS=1
fi

# 2. the control is left alone
if grep "^$EXPECTED," "$RESULTS" | grep -q ",$CONTROL,"; then
  echo "CT-1: FAIL -- $EXPECTED was also reported for $CONTROL, which both queries" >&2
  echo "      build identically. The check is reporting agreement as drift." >&2
  STATUS=1
else
  echo "CT-1: $CONTROL not reported -- both queries build it identically, and the"
  echo "      check leaves it alone."
fi

# 3. nothing turned up that nobody chose
REPORTED=$(tail -n +2 "$RESULTS" | cut -d, -f1 | sort -u)
UNEXPECTED=$(echo "$REPORTED" | grep -vx "$EXPECTED" | grep -vxF "$(echo "$ALLOWED" | tr ' ' '\n')" || true)
if [ -n "$UNEXPECTED" ]; then
  echo "CT-1: FAIL -- findings nobody chose:" >&2
  echo "$UNEXPECTED" | sed 's/^/  /' >&2
  echo "      Either the data grew a second defect, or the suite has a false positive." >&2
  STATUS=1
fi

if [ "$STATUS" -eq 0 ]; then
  echo "CT-1: PASS"
  echo "      Findings: $OUT/findings.txt"
fi
exit "$STATUS"
